mapper.sql:
l.is_delete = 0 and o.is_delete = 0 and m.is_delete = 0
and (o.order_no like concat('%', #{query.keyword}, '%') or l.carrier like concat('%', #{query.keyword}, '%') or l.tracking_no like concat('%', #{query.keyword}, '%'))
and (m.member_code like concat('%', #{query.merchantKeyword}, '%') or m.nickname like concat('%', #{query.merchantKeyword}, '%') or m.legal_subject_name like concat('%', #{query.merchantKeyword}, '%'))
and l.direction = #{query.direction}
and l.route_status = #{query.routeStatus}
and l.abnormal_flag = 1
